Here is the root cause:
In compat ioctl handling for wireless extensions (wext), the local `struct iw_point iwp` is declared and its fields (`pointer`, `length`, `flags`) are assigned from the compat structure, but the entire structure is not zero-initialized. On 64-bit architectures, `struct iw_point` contains a 32-bit padding hole between the `flags` field and the end of the structure. This padding remains uninitialized, and when the structure is later copied to user space, those bytes leak kernel memory, resulting in an information disclosure vulnerability (kernel-infoleak).

Here is the patch:
 #ifdef CONFIG_COMPAT
 static int compat_standard_call(struct net_device	*dev,
 				struct iwreq		*iwr,
 				unsigned int		cmd,
 				struct iw_request_info	*info,
 				iw_handler		handler)
 {
 	const struct iw_ioctl_description *descr;
 	struct compat_iw_point *iwp_compat;
 	struct iw_point iwp;
 	int err;

 	descr = standard_ioctl + IW_IOCTL_IDX(cmd);

 	if (descr->header_type != IW_HEADER_TYPE_POINT)
 		return ioctl_standard_call(dev, iwr, cmd, info, handler);

 	iwp_compat = (struct compat_iw_point *) &iwr->u.data;
+
+	/* struct iw_point has a 32bit hole on 64bit arches. */
+	memset(&iwp, 0, sizeof(iwp));
+
 	iwp.pointer = compat_ptr(iwp_compat->pointer);
 	iwp.length = iwp_compat->length;
 	iwp.flags = iwp_compat->flags;

 	err = ioctl_standard_iw_point(&iwp, cmd, descr, handler, dev, info);

 	iwp_compat->pointer = ptr_to_compat(iwp.pointer);
 	iwp_compat->length = iwp.length;
 	iwp_compat->flags = iwp.flags;

 	return err;
 }



